```dataviewjs
// ================= 极简配置区域 =================

// 1. 人物姓名 (如果留空，直接进入“旁白模式”)
const charName = "{{VALUE:人物姓名(留空=旁白)}}";

// 2. 图片路径 (如果留空，且有名字，进入“无图对话模式”)
const myImagePath = "{{VALUE:图片路径(可空)}}"; 

// 3. 文本内容 (自动处理换行)
const textMain = `{{VALUE:中文正文}}`.replace(/\\n/g, "\n");
const textSub = `{{VALUE:英文正文}}`.replace(/\\n/g, "\n");

// 4. 颜色与速度设置
const nameColor = "#666666"; // ★ 已修改为深灰色
const mainColor = "#e0e0e0"; 
const subColor  = "#777777"; 
const speed = 45; 

// ================= 智能逻辑核心 =================

// 数据清洗
const hasName = charName && charName.trim().length > 0;
const hasImage = myImagePath && myImagePath.trim().length > 0 && myImagePath !== "Assets/default.png";

// --- 模式自动判断 ---
// 默认为标准 AVG 模式
let containerClass = "hybrid-container"; 
let showRole = true; // 是否显示角色信息层

if (!hasName) {
    // 【情况1】没名字 -> 旁白模式
    containerClass += " no-role";
    showRole = false; 
} else if (!hasImage) {
    // 【情况2】有名字没图 -> 无图对话模式
    containerClass += " no-img";
    // showRole 依然为 true，因为要显示名字
}
// 【情况3】有名字有图 -> 保持默认 containerClass，showRole = true

// ================= 渲染层 =================

const container = dv.el("div", "", { cls: containerClass });

// 1. 渲染图片 (只有在 标准模式 下才渲染)
if (showRole && hasImage) {
    try {
        const charImgSrc = app.vault.adapter.getResourcePath(myImagePath);
        const img = container.createEl("img", { cls: "hybrid-char-img" });
        img.src = charImgSrc;
    } catch (e) {
        console.error("图片路径无效", e);
    }
}

// 2. 创建面板
const panel = container.createEl("div", { cls: "hybrid-panel" });

// 3. 渲染名字 (旁白模式下不渲染)
if (showRole && hasName) {
    const nameTag = panel.createEl("div", { cls: "hybrid-name", text: charName });
    nameTag.style.color = nameColor;
}

// 4. 渲染文字
const mainSpan = panel.createEl("div", { cls: "hybrid-text-main" });
mainSpan.style.color = mainColor;

const subSpan = panel.createEl("div", { cls: "hybrid-text-sub" });
subSpan.style.color = subColor;

// 5. 光标
panel.createEl("div", { cls: "hybrid-cursor", text: "▼" });

// ================= 打字机逻辑 =================
let i = 0;
let j = 0;

function typeWriter() {
  if (i < textMain.length) {
    if (textMain.charAt(i) === "\n") mainSpan.innerHTML += "<br/>";
    else mainSpan.innerText += textMain.charAt(i);
    i++;
    setTimeout(typeWriter, speed);
  } else if (j < textSub.length) {
    if (textSub.charAt(j) === "\n") subSpan.innerHTML += "<br/>";
    else subSpan.innerText += textSub.charAt(j);
    j++;
    setTimeout(typeWriter, speed / 1.5); 
  }
}

setTimeout(typeWriter, 400);
